import{_ as r,a0 as n,w as p,s as o,I as t,x as e,a1 as s,A as l,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"用 PGP 保护代码完整性（二）：生成你的主密钥 | LCTT x X-CMD","titleTemplate":false,"description":"用 PGP 保护代码完整性（二）：生成你的主密钥 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 PGP 保护代码完整性（二）：生成你的主密钥 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 PGP 保护代码完整性（二）：生成你的主密钥 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180221 Protecting Code Integrity with PGP - Part 2- Generating Your Master Key","title":"用 PGP 保护代码完整性（二）：生成你的主密钥","tag":"201804","desc":""},"relativePath":"201804/20180221 Protecting Code Integrity with PGP - Part 2- Generating Your Master Key.md","filePath":"[post].md"}'),g={name:"201804/20180221 Protecting Code Integrity with PGP - Part 2- Generating Your Master Key.md"};function h(u,i,k,b,c,f){const a=n("Link");return p(),o("div",null,[i[19]||(i[19]=t("h1",{id:"用-pgp-保护代码完整性-二-生成你的主密钥",tabindex:"-1"},[e("用 PGP 保护代码完整性（二）：生成你的主密钥 "),t("a",{class:"header-anchor",href:"#用-pgp-保护代码完整性-二-生成你的主密钥","aria-label":"Permalink to “用 PGP 保护代码完整性（二）：生成你的主密钥”"},"​")],-1)),i[20]||(i[20]=t("p",null,[t("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/binary-1538717_1920.png?itok=kv_sxSnf",alt:""})],-1)),t("p",null,[i[1]||(i[1]=e("在本系列文章中，我们将深度探讨如何使用 PGP 以及为工作于自由软件项目的开发者提供实用指南。在前一篇文章中，我们介绍了",-1)),s(a,{href:"https://linux.cn/article-9524-1.html"},{default:l(()=>[...i[0]||(i[0]=[e("基本工具和概念",-1)])]),_:1}),i[2]||(i[2]=e("。在本文中，我们将展示如何生成和保护你的 PGP 主密钥。",-1))]),i[21]||(i[21]=d(`<h3 id="清单" tabindex="-1">清单 <a class="header-anchor" href="#清单" aria-label="Permalink to “清单”">​</a></h3><ol><li>生成一个 4096 位的 RSA 主密钥 （必要）</li><li>使用 paperkey 备份你的 RSA 主密钥 （必要）</li><li>添加所有相关的身份 （必要）</li></ol><h3 id="考虑事项" tabindex="-1">考虑事项 <a class="header-anchor" href="#考虑事项" aria-label="Permalink to “考虑事项”">​</a></h3><h3 id="理解-主-认证-密钥" tabindex="-1">理解“主”（认证）密钥 <a class="header-anchor" href="#理解-主-认证-密钥" aria-label="Permalink to “理解“主”（认证）密钥”">​</a></h3><p>在本节和下一节中，我们将讨论“主密钥”和“子密钥”。理解以下内容很重要：</p><ol><li>在“主密钥”和“子密钥”之间没有技术上的区别。</li><li>在创建时，我们赋予每个密钥特定的能力来分配功能限制。</li><li>一个 PGP 密钥有四项能力 * [S] 密钥可以用于签名 * [E] 密钥可以用于加密 * [A] 密钥可以用于身份认证 * [C] 密钥可以用于认证其他密钥</li><li>一个密钥可能有多种能力</li></ol><p>带有 [C] （认证）能力的密钥被认为是“主”密钥，因为它是唯一可以用来表明与其他密钥关系的密钥。只有 [C] 密钥可以被用于：</p><ul><li>添加或撤销其他密钥（子密钥）的 S/E/A 能力</li><li>添加、更改或撤销密钥关联的身份（uid）</li><li>添加或更改本身或其他子密钥的到期时间</li><li>为了网络信任目的为其它密钥签名</li></ul><p>在自由软件的世界里，[C] 密钥就是你的数字身份。一旦你创建该密钥，你应该格外小心地保护它并且防止它落入坏人的手中。</p><h3 id="在你创建主密钥前" tabindex="-1">在你创建主密钥前 <a class="header-anchor" href="#在你创建主密钥前" aria-label="Permalink to “在你创建主密钥前”">​</a></h3><p>在你创建的你的主密钥前，你需要选择你的主要身份和主密码。</p><h4 id="主要身份" tabindex="-1">主要身份 <a class="header-anchor" href="#主要身份" aria-label="Permalink to “主要身份”">​</a></h4><p>身份使用邮件中发件人一栏相同格式的字符串：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Alice Engineer &lt;alice.engineer@example.org&gt;</span></span></code></pre></div><p>你可以在任何时候创建新的身份，取消旧的，并且更改你的“主要”身份。由于主要身份在所有 GnuPG 操作中都展示，你应该选择正式的和最有可能用于 PGP 保护通信的名字和邮件地址，比如你的工作地址或者用于在项目<ruby>提交<rt>commit</rt></ruby>时签名的地址。</p><h4 id="密码" tabindex="-1">密码 <a class="header-anchor" href="#密码" aria-label="Permalink to “密码”">​</a></h4><p><ruby>密码<rt>passphrase</rt></ruby>专用于私钥存储在磁盘上时使用对称加密算法对其进行加密。如果你的 <code>.gnupg</code> 目录的内容被泄露，那么一个好的密码就是小偷能够在线假冒你的最后一道防线，这就是为什么设置一个好的密码很重要的原因。</p><p>一个强密码最好使用丰富或混合的词典的 3-4 个词，而不引用自流行来源（歌曲、书籍、口号）。由于你将相当频繁地使用该密码，所以它应当易于输入和记忆。</p><h4 id="算法和密钥强度" tabindex="-1">算法和密钥强度 <a class="header-anchor" href="#算法和密钥强度" aria-label="Permalink to “算法和密钥强度”">​</a></h4><p>尽管现在 GnuPG 已经支持椭圆曲线加密一段时间了，但我们仍坚持使用 RSA 密钥，至少较长一段时间会这样。虽然现在就可以开始使用 ED25519 密钥，但你可能会碰到无法正确处理它们的工具和硬件设备。</p><p>在后续的指南中我们说 2048 位的密钥对 RSA 公钥加密的生命周期已经足够，你可能也会好奇主密钥为什么是 4096 位。 原因很大程度是由于社会因素而非技术上的：主密钥在密钥链上是最显眼的，如果你的主密钥位数比一些和你交互的开发者的少，他们肯定会鄙视你。</p><h4 id="生成主密钥" tabindex="-1">生成主密钥 <a class="header-anchor" href="#生成主密钥" aria-label="Permalink to “生成主密钥”">​</a></h4><p>为了生成你的主密钥，请使用以下命令，并且将 “Alice Engineer” 替换为正确值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --quick-generate-key &#39;Alice Engineer &lt;alice@example.org&gt;&#39; rsa4096 cert</span></span></code></pre></div><p>这将弹出一个要求输入密码的对话框。然后，你可能需要移动鼠标或随便按一些键才能生成足够的熵，直到该命令完成。</p><p>查看命令输出，它就像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pub rsa4096 2017-12-06 [C] [expires: 2019-12-06]</span></span>
<span class="line"><span> 111122223333444455556666AAAABBBBCCCCDDDD</span></span>
<span class="line"><span>uid Alice Engineer &lt;alice@example.org&gt;</span></span></code></pre></div><p>注意第二行的长字符串 —— 它是你新生成的密钥的完整指纹。密钥 ID（Key ID）可以用以下三种不同形式表达：</p><ul><li><ruby>指纹<rt>Fingerprint</rt></ruby>，一个完整的 40 个字符的密钥标识符</li><li><ruby>长密钥 ID<rt>Long</rt></ruby>，指纹的最后 16 个字符（AAAABBBBCCCCDDDD）</li><li><ruby>短密钥 ID<rt>Short</rt></ruby>，指纹的最后 8 个字符（CCCCDDDD）</li></ul><p>你应该避免使用 8 个字符的短密钥 ID，因为它们不足够唯一。</p><p>这里，我建议你打开一个文本编辑器，复制你新密钥的指纹并粘贴。你需要在接下来几步中用到它，所以将它放在旁边会很方便。</p><h4 id="备份你的主密钥" tabindex="-1">备份你的主密钥 <a class="header-anchor" href="#备份你的主密钥" aria-label="Permalink to “备份你的主密钥”">​</a></h4><p>出于灾后恢复的目的 —— 同时特别的如果你试图使用 Web of Trust 并且收集来自其他项目开发者的密钥签名 —— 你应该创建你的私钥的硬拷贝备份。万一所有其它的备份机制都失败了，这应当是最后的补救措施。</p><p>创建一个你的私钥的可打印的硬拷贝的最好方法是使用为此而写的软件 <code>paperkey</code>。<code>paperkey</code> 在所有 Linux 发行版上可用，在 Mac 上也可以通过 brew 安装 <code>paperkey</code>。</p><p>运行以下命令，用你密钥的完整指纹替换 <code>[fpr]</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --export-secret-key [fpr] | paperkey -o /tmp/key-backup.txt</span></span></code></pre></div><p>输出将采用易于 OCR 或手动输入的格式，以防如果你需要恢复它的话。打印出该文件，然后拿支笔，并在纸的边缘写下密钥的密码。这是必要的一步，因为密钥输出仍然使用密码加密，并且如果你更改了密钥的密码，你不会记得第一次创建的密钥是什么 —— 我保证。</p><p>将打印结果和手写密码放入信封中，并存放在一个安全且保护好的地方，最好远离你家，例如银行保险库。</p><p><strong>打印机注意事项</strong> 打印机连接到计算机的并行端口的时代已经过去了。现在他们拥有完整的操作系统，硬盘驱动器和云集成。由于我们发送给打印机的关键内容将使用密码进行加密，因此这是一项相当安全的操作，但请使用您最好的偏执判断。</p><h4 id="添加相关身份" tabindex="-1">添加相关身份 <a class="header-anchor" href="#添加相关身份" aria-label="Permalink to “添加相关身份”">​</a></h4><p>如果你有多个相关的邮件地址（个人、工作、开源项目等），你应该将其添加到主密钥中。你不需要为任何你不希望用于 PGP 的地址（例如，可能不是你的校友地址）这样做。</p><p>该命令是（用你完整的密钥指纹替换 <code>[fpr]</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --quick-add-uid [fpr] &#39;Alice Engineer &lt;allie@example.net&gt;&#39;</span></span></code></pre></div><p>你可以查看你已经使用的 UID：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --list-key [fpr] | grep ^uid</span></span></code></pre></div><h4 id="选择主-uid" tabindex="-1">选择主 UID <a class="header-anchor" href="#选择主-uid" aria-label="Permalink to “选择主 UID”">​</a></h4><p>GnuPG 将会把你最近添加的 UID 作为你的主 UID，如果这与你想的不同，你应该改回来：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --quick-set-primary-uid [fpr] &#39;Alice Engineer &lt;alice@example.org&gt;&#39;</span></span></code></pre></div><p>下次，我们将介绍如何生成 PGP 子密钥，它是你实际用于日常工作的密钥。</p>`,49)),t("p",null,[i[4]||(i[4]=e("通过 Linux 基金会和 edX 的免费",-1)),s(a,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:l(()=>[...i[3]||(i[3]=[e("“Introduction to Linux” ",-1)])]),_:1}),i[5]||(i[5]=e("课程了解关于 Linux 的更多信息。",-1))]),i[22]||(i[22]=t("hr",null,null,-1)),t("p",null,[i[7]||(i[7]=e("via: ",-1)),s(a,{href:"https://www.linux.com/blog/learn/PGP/2018/2/protecting-code-integrity-pgp-part-2-generating-and-protecting-your-master-pgp-key"},{default:l(()=>[...i[6]||(i[6]=[e("https://www.linux.com/blog/learn/PGP/2018/2/protecting-code-integrity-pgp-part-2-generating-and-protecting-your-master-pgp-key",-1)])]),_:1})]),t("p",null,[i[11]||(i[11]=e("作者：",-1)),s(a,{href:"https://www.linux.com/users/mricon"},{default:l(()=>[...i[8]||(i[8]=[e("KONSTANTIN RYABITSEV",-1)])]),_:1}),i[12]||(i[12]=e(" 译者：",-1)),s(a,{href:"https://github.com/kimii"},{default:l(()=>[...i[9]||(i[9]=[e("kimii",-1)])]),_:1}),i[13]||(i[13]=e(" 校对：",-1)),s(a,{href:"https://github.com/wxy"},{default:l(()=>[...i[10]||(i[10]=[e("wxy",-1)])]),_:1})]),t("p",null,[i[16]||(i[16]=e("本文由 ",-1)),s(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[14]||(i[14]=[e("LCTT",-1)])]),_:1}),i[17]||(i[17]=e(" 原创编译，",-1)),s(a,{href:"https://linux.cn/"},{default:l(()=>[...i[15]||(i[15]=[e("Linux中国",-1)])]),_:1}),i[18]||(i[18]=e(" 荣誉推出",-1))])])}const x=r(g,[["render",h]]);export{y as __pageData,x as default};
